const STATUS = ["baru", "diproses", "dikirim", "selesai"] as const;
type Status = (typeof STATUS)[number];

function berikutnya(s: Status): Status {
  const i = STATUS.indexOf(s);
  return STATUS[Math.min(i + 1, STATUS.length - 1)];
}
let s: Status = "baru";
s = berikutnya(s);
s = berikutnya(s);
console.log(s);
console.log(berikutnya("selesai"));

