const KATEGORI = ["makanan", "minuman", "snack"] as const;
type Kategori = (typeof KATEGORI)[number];
type Item = { nama: string; kategori: Kategori };
function hitung(daftar: Item[], k: Kategori): number {
  return daftar.filter((x) => x.kategori === k).length;
}
const menu: Item[] = [
  { nama: "Kopi", kategori: "minuman" },
  { nama: "Roti", kategori: "makanan" },
  { nama: "Teh", kategori: "minuman" },
];
console.log(hitung(menu, "minuman"));
